const src = $input.first().json;
const body = src.body ?? src;

const question = typeof body.question === 'string'
  ? body.question.trim()
  : '';

const supplied = body.session_id;

const isEmpty = supplied == null ||
  (typeof supplied === 'string' && supplied.trim() === '');

const isValidId = typeof supplied === 'string' &&
  /^[a-zA-Z0-9_-]{16,128}$/.test(supplied);

const session_id = isValidId
  ? supplied
  : 'session_' + $execution.id + '_' +
    Math.random().toString(36).slice(2).padEnd(12, '0');

const valid =
  question.length > 0 &&
  question.length <= 2000 &&
  (isEmpty || isValidId);

const email =
  typeof body.email === 'string' &&
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email) &&
  body.email.length <= 254
    ? body.email
    : '';

return [{
  json: {
    ok: valid,
    question,
    session_id,
    request_id: String($execution.id),
    started_at: Date.now(),
    email,
    status: valid ? 'pending' : 'error',
    httpStatus: valid ? 200 : 400,
    answer: valid ? '' :
      'Введите вопрос (до 2000 символов) и корректный идентификатор сессии.',
    sources: []
  }
}];

