const d=$('08 Поисковый запрос').first().json;const map=new Map();
for(const item of $input.all()){const points=item.json.result?.points;if(!Array.isArray(points))throw Error('Некорректный ответ Qdrant');for(const p of points){const id=String(p.id);const x=map.get(id)||{id,payload:p.payload||{},vector_score:0,text_match:false};if(typeof p.score==='number')x.vector_score=p.score;else x.text_match=true;map.set(id,x);}}
const tokens=s=>new Set((String(s).toLowerCase().match(/[\p{L}\p{N}-]+/gu)||[]));
const ranked=[...map.values()].map(x=>{const words=tokens(x.payload.text??x.payload.content??'');const hits=d.keywords.filter(k=>words.has(k)).length;return {...x,hits,rank:x.vector_score+Math.min(hits,5)*0.12+(x.text_match?0.05:0)};}).sort((a,b)=>b.rank-a.rank);
// Reserve slots for lexical-only hits, which may be absent from the vector top-20.
const lexical=ranked.filter(x=>x.text_match&&x.hits>0).sort((a,b)=>b.hits-a.hits||b.vector_score-a.vector_score).slice(0,4);
const selected=[...new Map([...lexical,...ranked.slice(0,8)].map(x=>[x.id,x])).values()].slice(0,10);
const parts=selected.map(x=>({name:String(x.payload.document_title??x.payload.source??''),section:String(x.payload.section??''),document_key:String(x.payload.document_key??''),chunk_index:x.payload.chunk_index??null,content:String(x.payload.text??x.payload.content??'').slice(0,3500),score:x.vector_score,kind:'regulation'})).filter(x=>x.name&&x.content);
// Expert answers are supplied separately and must be assessed for applicability by the model.
const experts=d.expert_answers.slice(0,30).map(e=>({name:'Разъяснение службы качества '+e.request_id,section:'',kind:'expert',content:'Вопрос: '+String(e.question).slice(0,1000)+'\nОтвет: '+String(e.expert_answer).slice(0,2000)}));
const all=[...parts,...experts].map((p,i)=>({...p,id:i+1}));
const context=all.map(p=>`[${p.id}] ${p.name} (${p.kind})\n${p.content}`).join('\n\n---\n\n');
return [{json:{...d,parts:all,context}}];

const r = $input.first().json;
const d = $('15 Гибридное ранжирование').first().json;

const c = r.choices?.[0];

// Проверка завершённости ответа модели
if (!c || c.finish_reason !== 'stop') {
  throw Error('Ответ модели не завершён');
}

// Преобразование ответа модели в JSON
const a = JSON.parse(
  c.message.content.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
);

// Проверка формата ответа
if (
  !['success', 'clarify', 'escalation', 'out_of_scope'].includes(a.status)
  || typeof a.answer !== 'string'
  || !a.answer.trim()
) {
  throw Error('Некорректный формат ответа');
}

// Корректировка противоречивого статуса
if (a.status === 'out_of_scope' && d.out_of_scope === false) {
  a.status = 'escalation';
}

// Нормализация формата ссылок
a.answer = a.answer.replace(
  /\[(?:ID\s*:\s*)?(\d+)(?:\s*,\s*(\d+(?:\.\d+)*(?:\s*[-–]\s*\d+(?:\.\d+)*)?))?\]/gi,
  (match, id, section) =>
    section ? `(п. ${section}) [${id}]` : `[${id}]`
);

// Ссылки в тексте ответа
let refs = [...new Set(
  [...a.answer.matchAll(/\[(\d+)\]/g)]
    .map(m => Number(m[1]))
)];

// Источники, указанные моделью отдельно
const declared = Array.isArray(a.source_ids)
  ? [...new Set(a.source_ids.map(Number))]
  : [];

// Допустимые идентификаторы источников
const valid = new Set(d.parts.map(p => p.id));

// Запрещаем ссылки на несуществующие источники
if ([...refs, ...declared].some(i => !valid.has(i))) {
  throw Error('Непроверяемые ссылки');
}

// Добавляем отсутствующие ссылки
for (const id of declared) {
  if (!refs.includes(id)) {
    a.answer += ` [${id}]`;
    refs.push(id);
  }
}

// Успешный ответ обязан содержать источник
if (a.status === 'success' && !refs.length) {
  throw Error('Ответ без подтверждённого источника');
}

// Ограничение количества уточнений
if (a.status === 'clarify' && d.round >= 3) {
  a.status = 'escalation';
  a.answer = 'После уточнений не удалось установить применимое правило. Требуется разъяснение службы качества.';
  refs = [];
}

// Формирование массива источников
const sources = d.parts
  .filter(p => refs.includes(p.id))
  .map(({ content, ...p }) => ({
    ...p,
    document: p.name,
    excerpt: content
  }));

// Явно обозначаем ответы по экспертным разъяснениям
if (
  a.status === 'success' &&
  sources.length > 0 &&
  sources.every(p => p.kind === 'expert')
) {
  a.answer = 'По разъяснению службы качества: ' + a.answer;
}

// Возвращаем проверенный результат
return [{
  json: {
    ...d,
    status: a.status,
    answer: a.answer,
    sources,
    answer_usage: r.usage ?? {}
  }
}];

