const usage={prompt_tokens:(d.analysis_usage?.prompt_tokens||0)+(d.answer_usage?.prompt_tokens||0),completion_tokens:(d.analysis_usage?.completion_tokens||0)+(d.answer_usage?.completion_tokens||0)};usage.total_tokens=usage.prompt_tokens+usage.completion_tokens;
